import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import Header from "../components/Header";
import Footer from "../components/Footer";
import Loader from "../components/Loader";
import PageTitleCard from "../components/PageTitleCard";
import { getTokenFromLS, getSubscriptionStatusFromLS } from "../commonFunctions";

export default function Aarti() {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const limit = 10; // Number of items per page

  useEffect(() => {
    async function fetchItems() {
      try {
        const res = await fetch(`https://api.bhaktibhav.app/frontend/all-artis?page=${currentPage}&limit=${limit}`);
        const json = await res.json();
        if (json?.status === "success") {
          if (currentPage === 1) {
            setItems(json.data || []);
          } else {
            setItems(prevItems => [...prevItems, ...(json.data || [])]);
          }
          
          // Check if there are more items to load
          if (!json.data || json.data.length < limit) {
            setHasMore(false);
          }
          
          console.log(json.data);
        } else {
          if (currentPage === 1) {
            setItems([]);
            alert("No data found!");
          }
        }
      } catch (error) {
        console.error("API Error:", error);
        if (currentPage === 1) {
          setItems([]);
        }
      } finally {
        setLoading(false);
        setLoadingMore(false);
      }
    }

    fetchItems();
  }, [currentPage]);

  // Infinite scroll handler
  useEffect(() => {
    const handleScroll = () => {
      if (loadingMore || !hasMore) return;

      const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
      const scrollHeight = document.documentElement.scrollHeight;
      const clientHeight = window.innerHeight;

      // Load more when user is near the bottom (100px before reaching the end)
      if (scrollTop + clientHeight >= scrollHeight - 100) {
        setLoadingMore(true);
        setCurrentPage(prevPage => prevPage + 1);
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, [loadingMore, hasMore]);

  if (loading) return <Loader message="🙏 Loading भक्ति भाव 🙏" size={200} />;

  if (!items.length)
    return <p className="text-center py-10 theme_text">❌ No items found</p>;

  const handleNavigate = (id, accessType) => {
    if (getSubscriptionStatusFromLS()) {
      return `/aarti/${id}`;
    } else {
      if (accessType === "free") {
        return `/aarti/${id}`;
      } else {
        if (getTokenFromLS()) {
          return "/payment";
        } else {
          return "/login";
        }
      }
    }

  }
  return (
    <>

      <Header pageName={{ hi: "vkjrh", en: "Aarti" }} />

      <PageTitleCard
        titleHi={"vkjrh"}
        titleEn={"Aarti"}
        customEngFontSize={"14px"}
        customFontSize={"23px"}
      />

      <div className="container mx-auto px-4 mt-6">
        <ul className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3">
          {items.map((item, idx) => {
            const imgSrc = item.imagethumb
              ? item.imagethumb.startsWith("http")
                ? item.imagethumb
                : `https://api.bhaktibhav.app${item.imagethumb}`
              : "/img/default-aarti.png";

            return (
              <li key={item._id || idx}>
                <Link
                  to={handleNavigate(item._id, item.accessType)}
                  className="relative block rounded-xl overflow-hidden shadow-lg"
                >
                  <div className={`overflow_bg`}>
                    <img
                      src={imgSrc}
                      alt={item.name?.en || item.name?.hi || "Aarti"}
                      className={`w-full rounded-md max-h-[150px] md:max-h-[150px] object-cover ${getSubscriptionStatusFromLS() ? "" : item.accessType === "paid" ? "blur" : ""}`}
                    />
                    <div className={`absolute inset-0 theme_text flex flex-col items-center justify-center text-center px-4 z-10 top-[35%] ${getSubscriptionStatusFromLS() ? "" : item.accessType === "paid" ? "blur-sm" : ""}`}>
                      {item.name?.hi && (
                        <h2 className="text-xl font-bold font-hindi">
                          {item.name.hi}
                        </h2>
                      )}
                      {item.name?.en && (
                        <p className="text-sm font-eng">{item.name.en}</p>
                      )}
                    </div>
                  </div>
                </Link>
              </li>
            );
          })}
        </ul>
      </div>

      {/* Loading indicator for infinite scroll */}
      {loadingMore && (
        <div className="flex justify-center items-center py-4">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-[#9A283D]"></div>
          <span className="ml-2 text-[#9A283D] font-eng">Loading more...</span>
        </div>
      )}

      {/* End of data indicator */}
      {/* {!hasMore && items.length > 0 && (
        <div className="text-center py-4 text-gray-500 font-eng">
          No more आरती to load
        </div>
      )} */}


    </>
  );
}
